from collections import deque

def cc4(grid, start, ok):
 seen={start}; q=[start]
 for p in q:
  r,c=p
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   n=(r+dr,c+dc)
   if 0<=n[0]<len(grid) and 0<=n[1]<len(grid[0]) and n not in seen and ok(grid[n[0]][n[1]]):
    seen.add(n);q.append(n)
 return seen

