def farthest_info(g, start):
 comp=cc4(g,start,lambda v:v in (0,4))
 dist={start:0}; q=deque([start])
 while q:
  r,c=q.popleft()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   n=r+dr,c+dc
   if n in comp and n not in dist:
    dist[n]=dist[r,c]+1;q.append(n)
 mx=max(dist.values())
 return len(comp),mx,[p for p,d in dist.items() if d==mx]
